.help-text {
  font-size: 0.875rem;
  color: #718096;
  margin-top: 0.375rem;
  line-height: 1.4;
}

.error-message {
  font-size: 0.875rem;
  color: #e53e3e;
  margin-top: 0.375rem;
  line-height: 1.4;
  min-height: 1.5rem;
}

.error-message:empty {
  display: none;
}

