.submit-button {
  width: 100%;
  padding: 0.875rem 1.5rem;
  background: linear-gradient(135deg, #3182ce 0%, #2c5aa0 100%);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.submit-button:hover {
  background: linear-gradient(135deg, #2c5aa0 0%, #1e3a8a 100%);
  box-shadow: 0 4px 12px rgba(49, 130, 206, 0.3);
}

.submit-button:focus {
  outline: none;
  box-shadow: 0 0 0 4px rgba(49, 130, 206, 0.2), 0 4px 12px rgba(49, 130, 206, 0.3);
}

.submit-button:active {
  transform: translateY(1px);
}

.submit-button:disabled {
  background: linear-gradient(135deg, #cbd5e0 0%, #a0aec0 100%);
  cursor: not-allowed;
  box-shadow: none;
}

/* Status messages */
.form-status {
  margin-top: 1.5rem;
  padding: 1rem;
  border-radius: 6px;
  font-size: 0.95rem;
  line-height: 1.5;
  min-height: 1.5rem;
}

.form-status.success {
  background-color: #f0fff4;
  color: #22543d;
  border: 1px solid #9ae6b4;
}

.form-status.error {
  background-color: #fff5f5;
  color: #742a2a;
  border: 1px solid #fc8181;
}

.form-status:empty {
