  input[type="tel"] {
    border: 2px solid CanvasText;
  }

  input[aria-invalid="true"] {
    border: 3px solid CanvasText;
  }

  .submit-button {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }

  .submit-button:focus {
    outline: 3px solid Highlight;
    outline-offset: 2px;
  }
}

