    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(trimmed)) {
      return { valid: false, message: 'Error: Enter a valid email like name@example.com.' };
    }

    return { valid: true, message: '' };
  }

  validatePhone(value) {
