      return { valid: false, message: 'Error: Full name must be at least 2 characters.' };
    }

    if (trimmed.length > 100) {
      return { valid: false, message: 'Error: Full name must be 100 characters or less.' };
    }

    return { valid: true, message: '' };
  }

  validateEmail(value) {
    const trimmed = value.trim();

    if (!trimmed) {
      return { valid: false, message: 'Error: Email address is required.' };
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(trimmed)) {
      return { valid: false, message: 'Error: Enter a valid email like name@example.com.' };
    }

    return { valid: true, message: '' };
  }

  validatePhone(value) {
    // Phone is optional, so empty is valid
    if (!value.trim()) {
      return { valid: true, message: '' };
    }

    // Accept common phone formats
    const phoneRegex = /^[\d\s\-()+]+$/;
    if (!phoneRegex.test(value)) {
      return { valid: false, message: 'Error: Phone must contain only digits, spaces, dashes, parentheses, or a plus sign.' };
    }

