    const digitsOnly = value.replace(/\D/g, '');
    if (digitsOnly.length < 7) {
      return { valid: false, message: 'Error: Phone must contain at least 7 digits.' };
    }

    if (digitsOnly.length > 15) {
      return { valid: false, message: 'Error: Phone must be 15 digits or fewer.' };
