 class ContactForm {
   constructor() {
     this.form = document.getElementById('contactForm');
     this.formStatus = document.getElementById('form-status');

     this.fields = {
       fullName: {
         element: document.getElementById('fullName'),
         errorElement: document.getElementById('fullName-error'),
         validate: (value) => this.validateFullName(value)
       },
       email: {
         element: document.getElementById('email'),
         errorElement: document.getElementById('email-error'),
         validate: (value) => this.validateEmail(value)
       },
       phone: {
         element: document.getElementById('phone'),
         errorElement: document.getElementById('phone-error'),
         validate: (value) => this.validatePhone(value)
       }
     };

     this.initEventListeners();
   }

   initEventListeners() {
     this.form.addEventListener('submit', (e) => this.handleSubmit(e));

     Object.values(this.fields).forEach(field => {
       field.element.addEventListener('blur', () => this.validateField(field));
       field.element.addEventListener('input', () => {
         if (field.element.hasAttribute('aria-invalid')) {
           this.validateField(field);
         }
       });
     });
   }

   validateFullName(value) {
     const trimmed = value.trim();

     if (!trimmed) {
       return { valid: false, message: 'Error: Full name is required.' };
     }

     if (trimmed.length < 2) {
       return { valid: false, message: 'Error: Full name must be at least 2 characters.' };
     }

     if (trimmed.length > 100) {
       return { valid: false, message: 'Error: Full name must be 100 characters or less.' };
     }

     return { valid: true, message: '' };
   }

   validateEmail(value) {
     const trimmed = value.trim();

     if (!trimmed) {
       return { valid: false, message: 'Error: Email address is required.' };
     }

     const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
     if (!emailRegex.test(trimmed)) {
       return { valid: false, message: 'Error: Enter a valid email like name@example.com.' };
     }

     return { valid: true, message: '' };
   }

   validatePhone(value) {
     // Phone is optional, so empty is valid
     if (!value.trim()) {
       return { valid: true, message: '' };
     }

     // Accept common phone formats
     const phoneRegex = /^[\d\s\-()+]+$/;
     if (!phoneRegex.test(value)) {
       return { valid: false, message: 'Error: Phone must contain only digits, spaces, dashes, parentheses, or a plus sign.' };
     }

     // At least 7 digits
     const digitsOnly = value.replace(/\D/g, '');
     if (digitsOnly.length < 7) {
       return { valid: false, message: 'Error: Phone must contain at least 7 digits.' };
     }

     if (digitsOnly.length > 15) {
       return { valid: false, message: 'Error: Phone must be 15 digits or fewer.' };
     }

     return { valid: true, message: '' };
   }

   validateField(field) {
     const value = field.element.value;
     const result = field.validate(value);

     if (result.valid) {
       field.element.removeAttribute('aria-invalid');
       field.errorElement.textContent = '';
     } else {
       field.element.setAttribute('aria-invalid', 'true');
       field.errorElement.textContent = result.message;
     }

     return result.valid;
   }

   validateForm() {
     let isValid = true;

     // Validate all fields except optional phone
     Object.entries(this.fields).forEach(([key, field]) => {
       if (!this.validateField(field)) {
         isValid = false;
       }
     });

     return isValid;
   }

   handleSubmit(e) {
     e.preventDefault();
     this.clearFormStatus();

     if (!this.validateForm()) {
       // Focus the first invalid field
       const firstInvalid = Object.values(this.fields).find(
         field => field.element.hasAttribute('aria-invalid')
       );

       if (firstInvalid) {
         firstInvalid.element.focus();
       }

       this.showFormStatus('Please correct the errors above.', 'error');
       return;
     }

     // Simulate form submission
     this.submitForm();
   }

   submitForm() {
     const formData = {
       fullName: this.fields.fullName.element.value.trim(),
       email: this.fields.email.element.value.trim(),
       phone: this.fields.phone.element.value.trim()
     };

     // Simulate an async request
     this.fields.fullName.element.disabled = true;
     this.fields.email.element.disabled = true;
     this.fields.phone.element.disabled = true;

     const submitButton = this.form.querySelector('button[type="submit"]');
     const originalButtonText = submitButton.textContent;
     submitButton.disabled = true;
     submitButton.textContent = 'Sending...';

     // Simulate network delay
     setTimeout(() => {
       this.fields.fullName.element.disabled = false;
       this.fields.email.element.disabled = false;
       this.fields.phone.element.disabled = false;
       submitButton.disabled = false;
       submitButton.textContent = originalButtonText;

       // Show success message
       this.showFormStatus(
         `Thank you, ${formData.fullName}! Your message has been sent successfully. We'll be in touch soon.`,
         'success'
       );

       // Reset form
       this.form.reset();

       // Clear any previous error states
       Object.values(this.fields).forEach(field => {
         field.element.removeAttribute('aria-invalid');
         field.errorElement.textContent = '';
       });
     }, 1500);
   }

   showFormStatus(message, type) {
     this.formStatus.textContent = message;
     this.formStatus.className = `form-status ${type}`;
     this.formStatus.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
   }

   clearFormStatus() {
     this.formStatus.textContent = '';
     this.formStatus.className = 'form-status';
   }
 }

 // Initialize the form when the DOM is ready
 if (document.readyState === 'loading') {
   document.addEventListener('DOMContentLoaded', () => {
     new ContactForm();
   });
 } else {
   new ContactForm();
 }

